/**
 * User & Role Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. Security: the identity write payload never carries
 * `passwordHash` — the backend omits it.
 *
 * Payload/query types stay local (they describe what the dashboard sends).
 */

import type { components } from "@/lib/types/api.generated"
import type { SearchableQuery } from "./common"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** Built-in role vocabulary, as the snapshot's `UserRole` enum. */
export type UserRole = Schemas["UserRole"]

/** Gender vocabulary, as the snapshot's `UserGender` enum. */
export type UserGender = NonNullable<Schemas["UserGender"]>

/**
 * Dashboard-facing user. `GET /users` and `GET /users/:id` return
 * `DashboardUserResponseDto` (dates as ISO strings, custom role as
 * `{ id, name }`); the write routes return `IdentityUserRecordDto` (dates as
 * ISO strings too, no `customRole` relation). This alias is the read shape the
 * dashboard renders.
 */
export type User = Schemas["DashboardUserResponseDto"]

/** One custom or system role (`IdentityRoleDto`). */
export type Role = Schemas["IdentityRoleDto"]

/** One permission row attached to a role (`IdentityRolePermissionDto`). */
export type RolePermission = Schemas["IdentityRolePermissionDto"]

/**
 * Permission matrix cell. `GET /permissions` returns `{ id, module, action }`
 * while role rows carry `{ id, customRoleId, action, subject, createdAt }`.
 * The matrix reads either `subject` or `module`, so this union models both.
 */
export type Permission = Schemas["IdentityPermissionCatalogEntryDto"] | RolePermission

/* ─── Roles the dashboard can assign (built-in subset) ─── */

export type TenantUserRole =
  | "ADMIN"
  | "RECEPTIONIST"
  | "ACCOUNTANT"
  | "EMPLOYEE"

/* ─── Query ─── */

export interface UserListQuery extends SearchableQuery {
  role?: UserRole
  isActive?: boolean
}

/* ─── Payloads (mirror the request DTOs) ─── */

/** Body of `POST /dashboard/identity/users` (`CreateUserDto`). */
export type CreateUserPayload = Schemas["CreateUserDto"]

/** Body of `PATCH /dashboard/identity/users/:id` (`UpdateUserDto`). */
export type UpdateUserPayload = Schemas["UpdateUserDto"]

/**
 * Body of `PATCH /dashboard/identity/users/:id/role` (`UpdateUserRoleDto`).
 * `isLive`-style defaults: the snapshot marks `role` optional but `customRoleId`
 * defaults to null — the dashboard always sends exactly one of them.
 */
export type UpdateUserRolePayload = Schemas["UpdateUserRoleDto"]

/** Body of `POST /dashboard/identity/users/:userId/roles` (`AssignRoleDto`). */
export type AssignRolePayload = Schemas["AssignRoleDto"]

/** Body of `POST /dashboard/identity/roles` (`CreateRoleDto`). */
export type CreateRolePayload = Schemas["CreateRoleDto"]

/** One permission entry sent with `POST /roles/:id/permissions`. */
export type RolePermissionPayload = NonNullable<Schemas["AssignPermissionsDto"]["permissions"]>[number]
